ee:variables.ee:set-variable:
if (!isEmpty(attributes.queryParams.state default "")) (
    "SELECT COUNT(*) AS count, case_type, state " ++
    "FROM cvd_case_master " ++
    "WHERE UPPER(state) = :state " ++
    "GROUP BY case_type, state"
) else (
    "SELECT COUNT(*) AS count, case_type, state " ++
    "FROM cvd_case_master " ++
    "GROUP BY case_type, state"
)

ee:message.ee:set-payload:
%dw 2.0
output application/json
// Fetching covid reports by state
fun vaccinatedByState(state) = (payload filter(($.STATE == state as String) and ($.CASE_TYPE == "vaccinated")) map {
	COUNT: $.COUNT
})[0]
---
((payload groupBy($.STATE) mapObject {
	caseReports: {
		state: $$,
		reports: {
			total: ($.COUNT reduce $ + $$) - (vaccinatedByState($$).COUNT as Number default 0),
			($ orderBy($.CASE_TYPE) map {
				($.CASE_TYPE): $.COUNT
			})
		}
	}
}).*caseReports) default []
